bounded_host_request.command:
set -euo pipefail
n=gace-createvdobot-videobot-poll-1
test "$(docker inspect -f '{{.State.Running}}' "$n" 2>/dev/null)" = true || { echo BOT_NOT_RUNNING; exit 81; }
docker logs --tail 500 "$n" 2>&1 | grep -q '^CREATOR_DM_POLL_READY=PASS$' || { echo BOT_POLL_NOT_READY; exit 82; }
docker logs --tail 500 "$n" 2>&1 | grep -q '^CREATOR_GATE_PUBLIC_RELEASE=CONNECTED$' || { echo BOT_GATE_NOT_CONNECTED; exit 83; }
docker exec "$n" grep -q "there is no text in the message to edit" /app/src/telegram/creatorScreenTransport.mjs || { echo BOT_MISSING_DM_RECOVERY_FIX; exit 84; }
docker exec "$n" grep -q "🎨 ステッカー・絵文字" /app/src/telegram/menuPanel.mjs || { echo BOT_HOME_MENU_SOURCE_MISSING; exit 85; }
test "$(docker ps --format '{{.Names}}' | grep -Ec 'createvdobot|create-videobot|videobot-poll' || true)" -eq 1 || { echo BOT_CONSUMER_CONFLICT; exit 86; }
echo BOT_MENU_ROUTE_PREFLIGHT_PASS
